import os
import re

# Search for submit functions in Python files
def search_submit_funcs(root_dir, max_results=20):
    results = []
    for root, dirs, files in os.walk(root_dir):
        # Skip system directories and large directories
        skip_dirs = {'node_modules', '.git', '__pycache__', '.venv', 'venv'}
        dirs[:] = [d for d in dirs if d not in skip_dirs]

        for f in files:
            if f.endswith('.py'):
                fpath = os.path.join(root, f)
                try:
                    with open(fpath, 'r', errors='ignore') as sf:
                        content = sf.read()
                        # Find def submit functions
                        matches = re.findall(r'def\s+(.*?)\.submit', content)
                        if matches:
                            results.append(fpath)
                            results.extend([m.strip() for m in matches])
                        if len(results) >= max_results:
                            return results
                except:
                    pass
    return results

